  "b2.farule2": "इन्कम टॅक्स घसारो दर ब्लॉकाचो वेगळो काडटात: ब्लॉक रेटाचेर रिटन डाउन व्हॅल्यू (देखीक प्लांट आनी मशिनरी 15%, फर्निचर 10%, कॉम्प्युटर 40%), वर्सांत 180 दिसां परस उणें वापरिल्ल्या ॲसेटाचेर अर्दो रेट, आनी विक्रेचे पयशे ब्लॉकांतल्यान उणे जातात. हें फकत इन्कम टॅक्स रिटर्नाखातीर, खात्यांत केन्नाच घालिनात. भरिल्ले रेट सादारण ब्लॉक रेट: तुमच्या अकाउंटंटा कडेन खात्री करात, खास करून 1 एप्रिल 2026 सावन इन्कम-टॅक्स ॲक्ट, 2025 खाला येवपी वर्सांखातीर.",
