  "hp.btn": "मजत: {what}",
  "hp.biz": "वयर छापता तो तुमच्या बिझनेसाचो तपशील. सुचोवण्यांतल्यान सेव केल्लो बिझनेस वेंचात, वा एक फावट बरयात, फुडल्या खेपे खातीर सेव जातलो.",
  "hp.details": "नंबर आनी तारीख. दर फायनान्शियल वर्सांत नंबर आपसूक वाडटा; तुमची स्वताची सिरीज आसल्यार बदलूं येता.",
  "hp.billto": "जाका बिल दितात तो. नांव बरोवंक सुरवात करात आनी सेव केल्लो कस्टमर वेंचात, वा नवो बरयात. GSTIN सावन स्टेट भरता; स्टेट CGST+SGST काय IGST तें थारायता.",
  "hp.vendor": "जाका ऑर्डर दितात तो सप्लायर. सेव केल्लो सप्लायर वेंचात वा नवो बरयात.",
  "hp.supplier": "नोंदणी नाशिल्लो जाचे कडल्यान विकत घेतलें. ह्या सेल्फ इनव्हॉयसाचेर GST रिव्हर्स चार्जांत तुमी स्वता भरतात.",
  "hp.consignee": "माल विकत घेवपी सोडून दुसऱ्या सुवातेर वा मनशाकडेन वता तेन्नाच भरात.",
  "hp.items": "दर आयटम वा सर्विसाची एक ओळ. सेव केल्लो आयटम वेंचल्यार रेट, HSN आनी GST भरतात, वा नवो बरयात. प्रमाण × रेट हातूंतल्यान डिस्काउंट वजा केल्यार टॅक्सेबल मोल.",
  "hp.notes": "अटी, बँक तपशील आनी छापील पानाचें रूप. फुडल्या खेपेखातीर डिफॉल्ट म्हूण सेव जाता.",
  "hp.einv": "ई-इनव्हॉयस वा ई-वे बिल गरजेचें आशिल्ल्या बिझनेसांखातीर: फायल डाउनलोड करात, सरकारी पोर्टलाचेर तुमच्या लॉगिनान अपलोड करात, उपरांत जाप हांगा लोड करात.",
  "hp.exp": "निर्यातीखातीर: शिपिंग बिल, पोर्ट आनी करन्सी. निर्यात झिरो-रेटेड: LUT आसल्यार GST ना; नासल्यार IGST भरून रिफंड मेळटा.",
  "hp.s.from": "जाणें तुमकां पयशे दिले. सेव केल्लो कस्टमर वेंचात वा नांव बरयात.",
  "hp.s.pay": "रक्कम, तारीख आनी कशे दिले. कायदेशीर मर्यादे परस चड कॅशीचेर शिटकावणी येता.",
  "hp.s.to": "जाका तुमी पयशे दिले. सेव केल्लो सप्लायर वेंचात वा नांव बरयात.",
  "hp.s.lines": "पयशे कसलेखातीर, दरेकाची एक ओळ (देखीक भाडें, दुरुस्ती, वाहतूक भाडें).",
  "hp.s.tdsrcm": "ह्या पेमेंटांतल्यान TDS कापलो जाल्यार, वा रिव्हर्स चार्जांत GST तुमकां भरचो आसल्यार भरात.",
  "hp.s.sign": "दिवपी, घेवपी आनी मान्यताय दिवप्याचीं नांवां. हातान सय करपाची आसल्यार रिकामें सोडात.",
  "hp.s.tenant": "भाडें कोण दिता आनी प्रॉपर्टीचो पत्तो.",
  "hp.s.landlord": "भाडें कोणाक मेळटा. HRA क्लेमाखातीर वर्साचें भाडें ₹1 लाखा परस चड आसल्यार घरमालकाचो PAN जाय.",
  "hp.s.rent": "म्हयन्याचें भाडें आनी खंयचे म्हयने. दर म्हयन्याची एक पावती तयार जाता.",
