  "hp.s.employer": "स्लिपाचेर छापता तसो तुमच्या बिझनेसाचो तपशील.",
  "hp.s.att": "म्हयन्याचे दीस आनी पगार मेळपाचे दीस. पगार नाशिल्ल्या रजेचो पगार कापता.",
  "hp.s.earn": "म्हयन्याचो बेसिक, भत्ते आनी हेर पगार.",
  "hp.s.ded": "PF, ESI, प्रोफेशनल टॅक्स, TDS आनी हेर कपात. बटण हें आपसूक काडूंक शकता.",
  "hp.s.entries": "दर ल्हान कॅश खर्च वा टॉप-अप, एक-एक ओळ. चालू बॅलन्स पेटयेंत कितले आसूंक जाय तें सांगता.",
  "hp.a.home": "आयजेची झलक: येवपाचे आनी दिवपाचे पयशे, थकिल्लीं बिलां आनी नव्यो एंट्री.",
  "hp.a.sales": "दर सेल आनी दर बिलाचेर कितलें उरलां. कोटेशन वा ऑर्डराचें हांगाच बिल करात.",
  "hp.a.buy": "परचेस बिलां, रिटर्न आनी खर्च. भरूंक नाशिल्लीं Dues त दिसतात.",
  "hp.a.money": "आयिल्ले आनी गेल्ले पयशे. दर पेमेंट ताच्या बिलांकडेन जोडात; उरिल्लें सगळ्यांत पोन्या बिलांक वता.",
  "hp.a.dues": "कोण तुमकां दितलो आनी तुमी कोणाक दितले, बिलाच्या पिरायेप्रमाण. हांगासावनच नम्र WhatsApp रिमाइंडर धाडात.",
  "hp.a.parties": "दर कस्टमर आनी सप्लायराचो बॅलन्स. स्टेटमेंटाखातीर उगडात.",
  "hp.a.cash": "तुमच्या एंट्रीं वयल्यान काडिल्ली हातांतली कॅश आनी बँक बॅलन्स.",
  "hp.a.khata": "सोंपें उदारेचें खातें: दर कस्टमरान किदें घेतलें आनी किदें दिलें.",
  "hp.a.preg": "सगळीं परचेस बिलां एकाच रजिस्टरांत, इनपुट टॅक्स क्रेडिटाखातीर GST सयत.",
  "hp.a.ebook": "पुराय वर्साचो खर्च, प्रकार आनी म्हयन्याप्रमाण.",
