  "hp.a.books": "कॅश बुक, बँक बुक आनी डे बुक, चालू बॅलन्सासयत.",
  "hp.m.biz": "तुमचे स्वताचे बिझनेस. डिफॉल्ट आशिल्लो नव्या डॉक्युमेंटांत भरता.",
  "hp.m.party": "कस्टमर आनी सप्लायर. दर डॉक्युमेंट टूलांत सुचोवणी म्हूण येतात.",
  "hp.m.item": "माल आनी सर्विस, रेट, HSN आनी GST सयत. CSV फायलीन एकाच फावटीं जायते इम्पोर्ट करात.",
  "hp.m.doc": "सगळ्या टूलांचे सेव केल्ले डॉक्युमेंट. Excel खातीर वळेरी डाउनलोड करात.",
  "hp.m.settings": "सगळ्या टूलांखातीर डिफॉल्ट बिझनेस, नंबर सिरीज आनी नव्या डॉक्युमेंटाचे डिफॉल्ट.",
  "hp.m.backup": "तुमचो डेटा ह्याच ब्राउझरांत आसा. सारकी बॅकअप फायल सेव करात आनी ह्या डिव्हायसा भायर दवरात.",
