  "hp.acct": "अकाउंटंटाखातीर एक .zip करता: Excel रजिस्टर, Tally फायली आनी डॉक्युमेंट. आमी कांयच धाडनात.",
  "hp.gdrive": "तुमचो डेटा तुमच्या स्वताच्या Google Drive च्या एका फायलींत कॉपी जाता आनी तुमी जोडटात त्या दर डिव्हायसाचेर एकसारको उरता. खंयचोय रेकॉर्ड दोन डिव्हायसांचेर बदल्लो जाल्यार सगळ्यांत नवो दवरतात आनी दुसरी कॉपी तुमचेखातीर सेव उरता.",
