  "it.t_data": "Data sheet",
  "it.year": "Tax year",
  "it.plan_h": "Estimate the year's income from your books, see the tax under both regimes, and plan the four advance tax instalments. Change any figure: your changes are kept on this device for this business and year.",
  "it.nobooks": "No sales or expenses are saved for this year yet, so the figures below start from zero. Type your own estimate.",
  "it.inputs": "Figures for the year",
