  "it.basis": "हे आंकडे कशाचेर आदारिल्ले ({d} दिसा प्रमाण)",
  "it.b1": "रेट ({d} दिसा प्रमाण), टॅक्स वर्स 2026-27: नवी रिजिम ₹4 लाख मेरेन शुन्य, ₹8 लाख मेरेन 5%, ₹12 लाख मेरेन 10%, ₹16 लाख मेरेन 15%, ₹20 लाख मेरेन 20%, ₹24 लाख मेरेन 25%, ताचे वयर 30%; ₹12 लाख मेरेनच्या उत्पन्नाक टॅक्स लागना अशें रिबेट, थोड्या वयर मार्जिनल रिलीफ; पगाराचेर ₹75,000 स्टँडर्ड डिडक्शन. पोरनी रिजिम: ₹2.5 लाख मेरेन शुन्य (60 वर्सां ₹3 लाख, 80 वर्सां ₹5 लाख), ₹5 लाख मेरेन 5%, ₹10 लाख मेरेन 20%, ताचे वयर 30%; ₹5 लाख मेरेन ₹12,500 रिबेट; ₹50,000 स्टँडर्ड डिडक्शन. सॅलरी स्लिप टूल आदींच वापरता तेच हे रेट; हें करतना Finance Act परत वाचूंक ना, देखून ते तपासात.",
  "it.b2": "ॲडव्हान्स टॅक्स (Income-tax Act 2025, सेक्शन 403 ते 408): TDS उपरांत टॅक्स ₹10,000 वा चड आसल्यार भरपाचो; 15 जून मेरेन 15%, 15 सप्टेंबर मेरेन 45%, 15 डिसेंबर मेरेन 75%, 15 मार्च मेरेन सगळो; प्रिझम्प्टिव्ह टॅक्सपेयर सगळो 15 मार्च मेरेन भरता; 31 मार्च मेरेनचें पेमेंट वर्साखातीर मेजता; बिझनेस उत्पन्न नाशिल्ल्या 60 वा चड पिरायेच्या रेसिडेंटाक सूट.",
  "it.b3": "व्याज: टॅक्साच्या 90% परस उणो भरल्यार उणावाचेर सेक्शन 424 (पोरनो 234B) म्हयन्याक वा म्हयन्याच्या भागाक 1%; सेक्शन 425 (पोरनो 234C) पयल्या तीन हप्त्यांच्या दरेक उणावाचेर 3% (15 जून मेरेन 12% आनी 15 सप्टेंबर मेरेन 36% भरल्यार ना) आनी मार्चाच्या उणावाचेर 1%.",
  "it.b4": "वयले सेक्शन 15 Nov 2026 दिसा Income Tax Department च्या वेबसायटीचेर (incometaxindia.gov.in) आशिल्ल्या अधिकृत टेक्स्टा कडेन उतर उतर तपासले. छापील Act निर्णय करता.",
  "it.b5": "हिशोबांतलो फायदो म्हळ्यार टॅक्सेबल फायदो न्हय: Act प्रमाण डेप्रिसिएशन, मान्य नाशिल्लो खर्च आनी प्रिझम्प्टिव्ह नेम तो बदलतात. हो प्लॅन आनी डेटा शीट तुमच्या अकाउंटंटाक दियात.",
  "it.b6": "हांगा काडना: सरचार्ज, खास रेटांनी कॅपिटल गेन, परदेशी टॅक्स रिलीफ, अल्पवयीनाच्या उत्पन्नाचेर टॅक्स आनी उशिरा फायलिंगाचेर व्याज.",
  "it.b7": "कांयच फायल जायना आनी तुमच्या हिशोबांत कांयच पोस्ट जायना.",
  "it.itr_h": "खंयचो रिटर्न फॉर्म जुळटा, कित्याक आनी खंयचे कागद तयार दवरचे तें पळोवपाक कांय प्रस्नांक जाप दियात.",
