  "it.w_pres2": "तुमच्या हेर जापांक लागून ITR-4 चलना, देखून बिझनेस उत्पन्न ITR-3 त वता.",
  "it.w_pres": "प्रिझम्प्टिव्ह बिझनेस उत्पन्न आनी सादें हेर उत्पन्न ITR-4 त बसता.",
  "it.w_simple": "मर्यादे भितर फकत पगार, घराची प्रॉपर्टी आनी व्याज ITR-1 त बसता.",
  "it.n_forms": "अटी 31 मार्च 2026 क सोंपिल्ल्या वर्साखातीर नोटिफाय केल्ल्या रिटर्नां प्रमाण आसात (टॅक्स पोर्टलांनी सांगिल्ल्या प्रमाण, ITR-1 आनी ITR-4 त आतां दोन मेरेन घरांच्यो प्रॉपर्टी चलतात). टॅक्स वर्स 2026-27 चे रिटर्न Income-tax Rules, 2026 खाला अजून नोटिफाय जावपाचे आसात: फायल करचे आदीं कोण तो फॉर्म वापरूंक शकना हाची फॉर्माचीच लिस्ट वाचात.",
  "it.n_ltcg": "लिस्टेड शेअर वा इक्विटी फंडांचेर ल्हान लाँग-टर्म गेन कांय वर्सां ITR-1 आनी ITR-4 त चलताले; 2026-27 खातीर हें पक्कें जावंक ना, देखून ITR-2 सुरक्षीत पर्याय आनी फॉर्माचीच लिस्ट निर्णय करता.",
  "it.n_ae": "सेक्शन 44AE (माल व्हरपी गाडयो) हाच्यो स्वताच्यो अटी आसात; प्रिझम्प्टिव्ह फॉर्म वापरचे आदीं त्यो तपासात.",
  "it.n_tax": "प्रिझम्प्टिव्ह रेटा परस उणो फायदो जाहीर करपाक हिशोब जाय आनी ऑडिट जाय पडूं येता: तेन्ना रिटर्न ITR-3.",
