  "ca.t": "म्हज्या अकाउंटंटाखातीर फायल",
  "ca.intro": "एक बिझनेस आनी काळ एकाच फकत वाचपाच्या फायलींत (.nsca) बांदता. ती तुमच्या अकाउंटंटाक WhatsApp वा ईमेलान धाडात. ते ती ca.niveshsahayak.in चेर उगडटात, हिशोब वाचतात, प्रस्न जोडटात आनी तुमकां कॉमेंट परत धाडटात.",
  "ca.notlive": "ही फायल दिवप, लायव्ह शेअर्ड लॉगिन न्हय. तुमी फायल केल्ली तेन्ना हिशोब जसो आशिल्लो तसो तुमच्या अकाउंटंटाक दिसता. लायव्ह लॉगिनाक तुमचे हिशोब दवरपी सर्वर जाय, आनी Nivesh Sahayak कडेन तो ना: तुमचे हिशोब तुमच्या डिव्हायसाचेर उरतात. नव्या एंट्रींखातीर नवी फायल करात.",
  "ca.what": "कितें भितर वता",
  "ca.earlier": "पयल्या तारखे आदल्यो एंट्रीय (सुरवातेच्या बॅलन्साखातीर आनी एजिंगाखातीर गरजेच्यो)",
  "ca.items": "खरेदी आनी विक्रीच्या दरां सयत आयटम लिस्ट (स्टॉकाखातीर गरजेची)",
  "ca.extra": "तुमी टिक केल्यारूच",
  "ca.extrah": "तुमी टिक करिना मेरेन सोडतात. फोटो (लोगो, सिग्नेचर), तुमचो PIN आनी बॅकअप सेटिंग केन्नाच घालनात.",
  "ca.orders": "कोटेशन, प्रोफॉर्मा इनवॉयस, सेल्स ऑर्डर, चलन आनी पर्चेस ऑर्डर",
  "ca.staff": "सॅलरी स्लिपो, स्टाफ ॲडव्हान्स, लोन आनी EMI, पेटी कॅश आनी कामगारांची लिस्ट",
