  "ca.msg": "{biz} चो {from} ते {to} मेरेनचो हिशोब. जोडिल्ली फायल {url} चेर उगडात (लॉगिन बगर चलता, कांयच अपलोड जायना). चेक कोड: {code}. ही आयज केल्ली फकत वाचपाची कॉपी; उपकार करून तुमचे प्रस्न कॉमेंट फायल म्हूण परत धाडात.",
  "ca.how": "फायल WhatsApp वा ईमेलान अटॅचमेंट म्हूण धाडात. WhatsApp नांवाच्या निमाणें .nsca दाखयता जाल्यार ताचें नांव बदलूं नाकात.",
  "ca.cT": "CA कॉमेंट",
  "ca.cIntro": "तुमचो अकाउंटंट प्रस्न आनी कॉमेंटांची एक ल्हान फायल (.nsca-comments) परत धाडटा. दर प्रस्न ताच्या एंट्री कुशीक पळोवपाक ती हांगा लोड करात. जाप दियात, बंद मार्क करात आनी परत धाडपाक फायल परत सेव करात.",
