  "ca.open": "उक्तें",
  "ca.gone": "(आतां तुमच्या हिशोबांत ना)",
  "ca.party": "पार्टी",
  "ca.screen": "स्क्रीन",
  "ca.general": "सादी कॉमेंट",
  "cv.h1": "अकाउंटंट व्ह्यूअर: तुमच्या क्लायंटान धाडिल्ली हिशोबाची फायल उगडात",
  "cv.intro": "तुमचो क्लायंट एका काळाचो आपलो हिशोब एकाच फायलींत बांदता आनी तुमकां WhatsApp वा ईमेलान धाडटा. ती हांगा उगडात आनी वाचात: येणें-देणें, पार्टी, लेजर, डे बुक, GST वर्कींग, फायनल अकाउंट्स आनी दरेक डॉक्युमेंट. सोदात आनी फिल्टर करात, खंयच्याय एंट्रीचेर प्रस्न विचारात आनी तुमच्यो कॉमेंट एका ल्हान फायलींत परत धाडात. फुकट, लॉगिन ना आनी कांयच अपलोड जायना: फायल तुमच्या ब्राउझरा भितर वाचतात.",
  "cv.drop": ".nsca फायल हांगा घालात",
  "cv.choose": "फायल वेंचात",
  "cv.dropnote": "फायल ह्याच डिव्हायसाचेर उरता. हांगा कांयच सेव जायना आनी हांगाच्यान तुमी तुमच्या क्लायंटाचो हिशोब बदलूंक शकनात.",
  "cv.nav.home": "सारांश",
  "cv.docs": "डॉक्युमेंट",
  "cv.day": "डे बुक",
  "cv.fin": "फायनल अकाउंट्स",
  "cv.gst": "GST वर्कींग",
  "cv.cT": "प्रस्न आनी कॉमेंट",
  "cv.how.h": "हें कशें चलता",
  "cv.how.1": "तुमचो क्लायंट Nivesh Sahayak उगडटा, म्हजो डेटा, अकाउंटंटाक धाडात हांगा वता आनी एका बिझनेसाखातीर आनी काळाखातीर \"म्हज्या अकाउंटंटाखातीर फायल करात\" वेंचता.",
  "cv.how.2": "ते तुमकां फायल (.nsca न सोंपपी) आनी एकाच मेसेजांत एक ल्हान चेक कोड धाडटात.",
  "cv.how.3": "तुमी ह्या पानार फायल उगडटात. पान फायल बदलूंक ना काय तें सांगता आनी तुळोवपाक तुमच्या क्लायंटान दिल्लो चेक कोड बरोवंक दिता.",
  "cv.how.4": "हिशोब वाचात, सोदात आनी खंयच्याय डॉक्युमेंटाचेर, डे-बुक एंट्रीचेर वा स्क्रीनाचेर \"प्रस्न वा कॉमेंट जोडात\" दाबात. तुमी बरयल्लें सगळें ह्याच ब्राउझरांत उरता.",
  "cv.how.5": "जाले उपरांत \"प्रस्न आनी कॉमेंट\" उगडात आनी ल्हान .nsca-comments फायल परत धाडात. तुमचो क्लायंट ती लोड करता आनी दर प्रस्न एंट्री कुशीक पळयता. ते जाप दिवं येतात, आनी तुमी जापो हांगा लोड करूं येतात.",
  "cv.live.h": "फायल दिवप, लायव्ह लॉगिन न्हय",
  "cv.live.p": "ही फायल दिवप. तुमी तुमच्या क्लायंटाच्या खात्यांत लॉगिन करिनात आनी ते मागीर करतात ते बदल तुमकां दिसनात. लायव्ह शेअर्ड लॉगिनाक हिशोब दवरपी सर्वर जाय, आनी Nivesh Sahayak कडेन तो ना: हिशोब तुमच्या क्लायंटाच्या डिव्हायसाचेर उरता. नव्या काळाखातीर वा दुरुस्ती उपरांत तुमच्या क्लायंटा कडल्यान नवी फायल मागात.",
  "cv.safe.h": "फायलींत कितें आसा आनी कितें ना",
  "cv.safe.p": "तुमचो क्लायंट कितें भितर वता तें टिक करता. सदांच्या प्रमाण फायलींत एका बिझनेसाच्यो काळाच्या निमाणे मेरेनच्यो एंट्री, पार्टी आनी आयटम आसतात. कोटेशन आनी ऑर्डरी, पगार आनी स्टाफाचे रेकॉर्ड, फोन नंबर आनी ईमेल पत्ते, आनी बिझनेसाच्या बँक खात्याचो तपशील तुमचो क्लायंट टिक करिना मेरेन सोडतात. फोटो, PIN आनी बॅकअप सेटिंग केन्नाच घालनात. फायलीक चेकसम आसता, देखून तातूंत जाल्लो खंयचोय बदल ह्या पानार दिसता. फायल बदलून चेकसम परत काडपी कोणाक चेकसम आडावंक शकना, देखून तुमच्या क्लायंटान वेगळो धाडिल्लो चेक कोड तुळयात.",
  "cv.readonly": "हें फायलीचें फकत वाचपाचें दृश्य: हांगा कांयच बदलूंक वा सेव करूंक जायना.",
  "cv.notfile": "ही Nivesh Sahayak ची अकाउंटंट फायल (.nsca) न्हय.",
  "cv.iscomments": "ही कॉमेंट फायल. पयलीं हिशोबाची फायल (.nsca) उगडात, मागीर \"प्रस्न आनी कॉमेंट\" हांगाच्यान कॉमेंट लोड करात.",
  "cv.newer": "ही फायल नव्या व्हर्जनान केल्ली. हें पान परत लोड करात आनी परत यत्न करात.",
  "cv.nostore": "तुमच्यो कॉमेंट ह्या ब्राउझरांत दवरूंक जाल्यो नात. कॉमेंट फायल आतांच सेव करात.",
