  "hm.h.margin.how": "निमाण्या 3 म्हयन्यांनी तुमी विकिल्ल्या दर 100 पयकीं, खरेदी आनी खर्चा उपरांत {p} उरले. ताचे आदल्या 3 म्हयन्यांनी: {q}.",
  "hm.h.margin.how1": "निमाण्या 3 म्हयन्यांनी तुमी विकिल्ल्या दर 100 पयकीं, खरेदी आनी खर्चा उपरांत {p} उरले.",
