  "hm.h.margin.ok": "मार्जिन उणें वा देंवता. तुमचे विक्रीचे दर आनी मुखेल आयटमांचो खर्च तपासात.",
  "hm.h.margin.low": "जवळ जवळ कांयच उरना. दर वाडयात, खर्च उणो करात वा लॉस जावपी आयटम विकप बंद करात.",
