  "hm.h.creep.ok": "खर्च वाडटा. रिपोर्ट स्क्रीनाचेर खंयचो हेड वाडलो तें पळयात.",
  "hm.h.creep.low": "खर्च खूब वाडलो. वाडिल्लो हेड सोदात, आनी तें एक फावटचें बिल न्हय तें तपासात.",
  "hm.h.creep.rule": "आदल्या पुराय म्हयन्याचो खर्च ताचे आदल्या 3 म्हयन्यांच्या सरासरी कडेन. 5% वा उणो वाडलो = 100, 40% वा चड वाडलो = 0. एक फावटचें व्हड बिल एका म्हयन्याखातीर स्कोर उणो करता.",
  "hm.rm.t": "ह्या डिव्हायसाचेर यादी",
  "hm.rm.p": "तुमी App उगडटात तेन्ना आयज कितें करचें तें दाखयता. सगळ्यांत तातडीच्या ओळींखातीर फोनाचेर नोटिफिकेशन दाखोवंकूय दिवं येता, दर एक दिसाक एक फावट.",
