  "hm.rm.l3": "चुकूंक फावनात अशा तारखांखातीर कॅलेंडर फायल वापरात: तुमच्या फोनाचें कॅलेंडर आपसूक वाजता. हें आयचें चित्र, देखून नवीं बिलां नोंद केल्या उपरांत नवी फायल करात.",
