  "au.h.client": "दर क्लायंट आनी वर्सा खातीर एक फायल. तुमच्या फर्माचो तपशील ह्या डिव्हायसार एकदांच दवरतात आनी तो दरेक सर्टिफिकेटार येता.",
  "au.h.fa": "दरेक ॲसेट एकदांच बरयात. रजिस्टर {y} खातीर कंपनीज ॲक्टाच्या शेड्यूल II प्रमाण आनी इन्कम टॅक्स ब्लॉका प्रमाण डेप्रिसिएशन आनी फरकाचेर डेफर्ड टॅक्स काडटा. फुडलें वर्स सुरू करात दाबल्यार क्लोजिंग आंकडे फुडें वतात.",
  "au.h.cf": "प्रॉफिट अँड लॉस अकाउंट आनी दोनूय बॅलन्स शीटांतले आंकडे बरयात. स्टेटमेंट इनडायरेक्ट पद्दतीन काडटा आनी सुरवातेच्या आनी निमाण्या कॅशा कडेन तपासता.",
  "au.h.ratio": "हें वर्स आनी फाटल्या वर्साचे आंकडे बरयात. शेड्यूल III मागता ते इकरा रेशो बदला सयत काडटात, आनी बदल 25% परस चड आसल्यार मार्क करतात.",
  "au.h.caro": "पयलीं ऑर्डर लागू जाता काय तें तपासात. मागीर दरेक क्लॉज मार्क करात, तुमचे रिमार्क आनी वर्किंग पेपर बरयात आनी फायली खातीर चेकलिस्ट प्रिंट करात.",
  "au.h.cert": "सर्टिफिकेट वा पत्र वेंचात, बॉक्स भरात आनी प्रिंट करात. यादीच्यो ओळी एका ओळीर एक बरयात, वर्णन आनी रक्कमे मदीं | घालून.",
