  "tf.f.127": "TCS बगर माल घेवपा खातीर खरेदीदाराचें डिक्लेरेशन",
  "tf.src": "19 नोव्हेंबर 2026 दिसा इन्कम टॅक्स ॲक्ट 2025 आनी इन्कम टॅक्स रुल्स 2026 (G.S.R. 198(E), 20 मार्च 2026) कडेन तपासलें. बिलांचेर TDS काडटना NSBiz हेंच टेबल वापरता.",
  "gb.h": "GST क्रेडिट ब्लॉक जालां? (सेक्शन 17(5))",
  "gb.lead": "कितें घेतलें तें वेंचात. सेक्शन 17(5) CGST ॲक्टा खाला इनपुट टॅक्स क्रेडिट ब्लॉक जालां काय आनी तें क्लेम करूंक दिवपी अपवाद चेकर सांगता.",
  "gb.q": "कितें घेतलें",
  "gb.blocked": "ब्लॉक",
  "gb.allowed": "क्रेडिट मेळूं येता",
  "gb.depends": "वापरा वयर आदारून",
  "gb.law": "कायदो",
  "gb.exc": "केन्ना क्रेडिट तरीय मेळटा",
  "gb.src": "फायनान्स ॲक्ट 2025 मेरेन बदल जाल्लें CGST ॲक्ट 2017 चें सेक्शन 17(5), 27 नोव्हेंबर 2026 दिसा वाचलें. फकत मार्गदर्शन, सल्लो न्हय: दरेक खरेदीचे फॅक्ट तपासात.",
  "gb.i.car": "मोटर कार वा लोकां खातीर हेर वाहन, 13 वा उण्यो सीट (ऑफिस वा स्टाफाच्या वापरा खातीर)",
  "gb.w.car": "ड्रायव्हर धरून 13 वा उण्या मनशांक बसपाची सोय आशिल्लें, लोकांक व्हरपी मोटर वाहन घेतल्यार क्रेडिट ब्लॉक आसा.",
  "gb.e.car": "जेन्ना वाहन तशा वाहनांच्या फुडल्या सप्लाया खातीर, भाड्यान प्रवाशांक व्हरपा खातीर, ड्रायव्हिंग शिकोवपा खातीर वा माल व्हरपा खातीर वापरतात.",
  "gb.i.carservice": "अशा वाहनाचो इन्शुरन्स, सर्व्हिसिंग वा दुरुस्ती",
  "gb.w.carservice": "ब्लॉक केल्ल्या वाहनाच्या जनरल इन्शुरन्स, सर्व्हिसिंग, दुरुस्ती आनी मेंटेनन्साचेर क्रेडिट ब्लॉक आसा.",
  "gb.e.carservice": "जेन्ना वाहन स्वता परवानगी आशिल्ल्या एका हेतू खातीर वापरतात, वा घेवपी अशीं वाहनां तयार करता वा तांचो इन्शुरर आसा.",
  "gb.i.truck": "माल वाहन, वा 13 परस चड सीट आशिल्लें वाहन",
  "gb.w.truck": "ब्लॉक ना: वाहन बिझनेसाच्या कामांत वा वाडी खातीर वापरल्यार क्रेडिट मेळटा.",
  "gb.i.food": "खाण, पेयां, आवटडोअर केटरिंग",
  "gb.w.food": "खाण आनी पेयां आनी आवटडोअर केटरिंगाचेर क्रेडिट ब्लॉक आसा.",
  "gb.e.food": "जेन्ना तशेंच आवटवर्ड सप्लाय करपाक वा कंपोझिट वा मिक्स्ड सप्लायाचो भाग म्हूण वापरतात; वा खंयच्याय कायद्या खाला एम्प्लॉयरान तें कर्मचाऱ्यांक दिवंक जाय.",
  "gb.i.beauty": "ब्युटी ट्रीटमेंट, हेल्थ सर्विस, कॉस्मेटिक वा प्लास्टिक सर्जरी",
  "gb.w.beauty": "क्रेडिट ब्लॉक आसा.",
  "gb.e.beauty": "जेन्ना तशेंच आवटवर्ड सप्लाय करपाक वा कंपोझिट वा मिक्स्ड सप्लायाचो भाग म्हूण वापरतात; वा खंयच्याय कायद्या खाला एम्प्लॉयरान तें दिवंक जाय.",
  "gb.i.rentcar": "कार भाड्यान वा लीजार घेवप (13 वा उण्यो सीट)",
  "gb.w.rentcar": "ब्लॉक केल्ल्या वाहनांच्या लीज, भाडें वा हायरिंगाचेर क्रेडिट ब्लॉक आसा.",
  "gb.e.rentcar": "जेन्ना वाहन परवानगी आशिल्ल्या हेतू खातीर वापरतात, वा हायरिंग तशेंच आवटवर्ड सप्लाय करपाक वापरतात; वा खंयच्याय कायद्या खाला एम्प्लॉयरान तें दिवंक जाय.",
  "gb.i.ins": "लायफ इन्शुरन्स वा हेल्थ इन्शुरन्स",
  "gb.w.ins": "क्रेडिट ब्लॉक आसा.",
  "gb.e.ins": "जेन्ना तशेंच आवटवर्ड सप्लाय करपाक वापरतात (इन्शुरर वा एजंट); वा खंयच्याय कायद्या खाला एम्प्लॉयरान तें कर्मचाऱ्यांक दिवंक जाय (देखीक लेबर कायद्यान मागिल्लो ग्रुप इन्शुरन्स).",
  "gb.i.club": "क्लब, हेल्थ वा फिटनेस सेंटराची मेंबरशिप",
  "gb.w.club": "क्रेडिट ब्लॉक आसा.",
  "gb.e.club": "फकत खंयच्याय कायद्या खाला एम्प्लॉयरान तें कर्मचाऱ्यांक दिवंक जाय तेन्ना.",
  "gb.i.ltc": "रजेचेर वा सुटयेर कर्मचाऱ्यांचो प्रवास (लीव्ह वा होम ट्रॅव्हल)",
  "gb.w.ltc": "सुटयेर कर्मचाऱ्यांक दिल्ल्या प्रवास सुविधांचेर क्रेडिट ब्लॉक आसा.",
